question.solution:
def clamp(value, low, high):
    if low > high:
        raise ValueError('下界不能大于上界')
    if value < low:
        return low
    if value > high:
        return high
    return value


CASES = [
    ((5, 0, 10), 5),
    ((-3, 0, 10), 0),
    ((99, 0, 10), 10),
    ((0, 0, 10), 0),
    ((10, 0, 10), 10),
    ((7, 7, 7), 7),
    ((2.5, 0.0, 2.0), 2.0),
    ((-7, -5, -1), -5),
]


def run_tests(fn):
    passed = 0
    failures = []
    for index, (args, expected) in enumerate(CASES, 1):
        try:
            actual = fn(*args)
        except Exception as exc:
            actual = f'抛异常 {type(exc).__name__}: {exc}'
        if actual == expected:
            passed += 1
        else:
            failures.append(f'用例 {index} 失败：clamp{args} 期望 {expected} 实际 {actual}')
    return passed, failures


ok, bad = run_tests(clamp)
print(f'通过 {ok}/{len(CASES)}')
for line in bad:
    print(line)
